declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientAllowedAudiencesAudienceAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedAudiencesAudienceAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAllowedAudiencesAudienceAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAudience returns null on a freshly created holder.
     */
    public function testAudienceNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAudienceAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAudienceAssigned());
        $this->assertNull($holder->getAudience());
    }
}
class ImplWithTrustedClientAllowedAudiencesAudienceAttributeHolderUnitTest
{
    use TrustedClientAllowedAudiencesAudienceAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAudienceRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAudience();
    }
}
